  'designFiles.documentTemplate.scenarioHeading': 'シナリオガイド',
  'designFiles.documentTemplate.scenario.prototype': 'プロトタイプでは、プロダクトの目標、ターゲットユーザー、フロー、画面、モジュール、インタラクション状態、レスポンシブのブレークポイント、そしてカラー、タイプ、間隔、角丸、モーションなどのデザイントークンを整理してください。',
  'designFiles.documentTemplate.scenario.wireframe': 'ワイヤーフレームでは、ユーザーフロー、画面一覧、レイアウト階層、コンテンツブロック、ローファイの制約、そしてビジュアルデザインの前に構造が答えるべき問いを記述してください。',
  'designFiles.documentTemplate.scenario.mobile': 'モバイルアプリでは、対象プラットフォーム、画面、ナビゲーションモデル、ジェスチャー、ネイティブパターン、デバイスサイズ、状態、モバイルのデザイントークンを列挙してください。',
  'designFiles.documentTemplate.scenario.slideDeck': 'スライドでは、ページ分けした PPT アウトラインを書いてください。スライドごとに 1 セクションとし、タイトル、目的、キーメッセージ、根拠、ビジュアルの方向性、スピーカーノート、エクスポートの要件を含めます。',
  'designFiles.documentTemplate.scenario.document': 'ドキュメントでは、読者、トーン、セクション構成、素材、引用やデータ、レイアウトの期待、PDF/エクスポートの要件を定義してください。',
  'designFiles.documentTemplate.scenario.image': '画像では、被写体、アスペクト比、構図、ビジュアルスタイル、ブランドトークン、参照ファイル、避けたい条件を指定してください。',
  'designFiles.documentTemplate.scenario.video': '動画では、シーン、タイミング、キャプション、モーション、アセット、音声のメモ、出力形式を含むストーリーボードを下書きしてください。',
  'designFiles.documentTemplate.scenario.hyperframes': 'HyperFrames では、HTML モーション作品について、シーン、タイムライン、キャプション、音に反応する場面、トランジション、キャプチャ/エクスポートの要件を記述してください。',
  'designFiles.documentTemplate.scenario.audio': '音声では、ボイスや音楽の方向性、長さ、ムード、スクリプトまたはコピー、ペース、発音のメモ、最終的な用途を定義してください。',
  'designFiles.documentTemplate.scenario.liveArtifact': 'ライブアーティファクトでは、データソース、更新頻度、ウィジェット、フィルター、インタラクション、空・読み込み・エラーの状態、アラートや自動化を記述してください。',
  'designFiles.documentTemplate.scenario.designSystem': 'デザインシステムでは、ブランドの目標、トークン、タイポグラフィ、カラー、間隔、コンポーネント、アセット、リファレンス、従うべき・避けるべきルールを列挙してください。',
