  'nextStep.planImproveBody': '最終成果物を生成する前に、現在のプランドキュメントを引き締めます。',
  'nextStep.planGeneratePrompt': '`{file}` を基準として使ってください。まずドキュメントを読み、その決定事項を維持したうえで、内容に合う最終的なデザイン成果物を生成してください。スライドのアウトラインならデッキを、PRD やプロトタイプの計画ならプロトタイプまたはワイヤーフレームを、ストーリーボードやクリエイティブブリーフなら対応するビジュアルまたはメディア成果物を生成します。生成する前に、解決できない TODO や矛盾があれば指摘してください。',
  'nextStep.planImprovePrompt': '`{file}` を読み、編集可能なプランドキュメントとしてその場で改善してください。スコープを絞り込み、弱いセクションを補い、不足している受け入れ確認を追加し、ユーザーの入力が必要な TODO や未解決の質問は残してください。最終的なデザイン成果物はまだ生成しないでください。',
  'nextStep.planImproveArtifactTitle': '成果物を改善',
