  'nextStep.planImproveArtifactPrompt': '`{artifact}` をその場で改善してください。既存の動作する成果物は維持し、プロダクト、ビジュアル、インタラクション、コンテンツの面で最も効果の高い改善を行ってください。すでに動作している挙動は保持し、最後に変更したファイルと残っているリスクをまとめてください。',
  'nextStep.planMergeTitle': 'ドキュメントと成果物を揃える',
  'nextStep.planMergeBody': 'プランと生成済みの成果物を突き合わせ、一緒に進められるようにします。',
  'nextStep.planMergePrompt': '`{document}` と `{artifact}` を合わせて読んでください。ドキュメントを意図、成果物を現在の実装として扱います。両者を整合させてください。確定した決定事項に合わせて成果物を更新し、古くなっている部分に限ってドキュメントを更新し、未解決の事項には明示的な TODO や未解決の質問を残してください。既存の動作する挙動は保持し、両方のファイルで何が変わったかをまとめてください。',

